CREATE TABLE IF NOT EXISTS mm_category(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,parent_id BIGINT NULL,kind VARCHAR(20) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_station_resource(id BIGINT PRIMARY KEY AUTO_INCREMENT,station_id BIGINT NOT NULL,resource_type VARCHAR(20) NOT NULL,equipment_id BIGINT NULL,user_id BIGINT NULL,name VARCHAR(100) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_sop(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,product_id BIGINT NOT NULL,operation_id BIGINT NOT NULL,version VARCHAR(32) NOT NULL,image_path VARCHAR(255) NOT NULL,enabled INT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_code_rule(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,prefix VARCHAR(32) NOT NULL,width INT NOT NULL DEFAULT 6,next_value BIGINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_defect(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,severity VARCHAR(20) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_check_subject(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,kind VARCHAR(20) NOT NULL,standard VARCHAR(500) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_check_plan_subject(id BIGINT PRIMARY KEY AUTO_INCREMENT,plan_id BIGINT NOT NULL,subject_id BIGINT NOT NULL,UNIQUE KEY uq_check_subject(plan_id,subject_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_check_due(id BIGINT PRIMARY KEY AUTO_INCREMENT,plan_id BIGINT NOT NULL,due_date DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',record_id BIGINT NULL,UNIQUE KEY uq_due(plan_id,due_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_holiday(id BIGINT PRIMARY KEY AUTO_INCREMENT,work_date DATE NOT NULL UNIQUE,is_working INT NOT NULL,name VARCHAR(100) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_rotation(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,station_id BIGINT NOT NULL,cycle_days INT NOT NULL DEFAULT 1,cycle_unit VARCHAR(20) NOT NULL DEFAULT 'DAY',mode VARCHAR(20) NOT NULL,is_generated INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CALL mm5_add_column('mm_rotation','cycle_unit','VARCHAR(20) NOT NULL DEFAULT ''DAY''');
CREATE TABLE IF NOT EXISTS mm_rotation_team(id BIGINT PRIMARY KEY AUTO_INCREMENT,rotation_id BIGINT NOT NULL,team_id BIGINT NOT NULL,sequence_no INT NOT NULL,UNIQUE KEY uq_rotation_team(rotation_id,team_id),UNIQUE KEY uq_rotation_seq(rotation_id,sequence_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_rotation_shift(id BIGINT PRIMARY KEY AUTO_INCREMENT,rotation_id BIGINT NOT NULL,shift_id BIGINT NOT NULL,sequence_no INT NOT NULL,UNIQUE KEY uq_rotation_shift(rotation_id,shift_id),UNIQUE KEY uq_rotation_shift_sequence(rotation_id,sequence_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_position(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,department_id BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_user_position(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,position_id BIGINT NOT NULL,UNIQUE KEY uq_position(user_id,position_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_menu(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,path VARCHAR(200) NOT NULL,parent_id BIGINT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_role_menu(id BIGINT PRIMARY KEY AUTO_INCREMENT,role_id BIGINT NOT NULL,menu_id BIGINT NOT NULL,UNIQUE KEY uq_role_menu(role_id,menu_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_parameter(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,value VARCHAR(500) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO mm_parameter(code,name,value) VALUES('APP_NAME','系统显示名称','Mouse MES'),('NOTICE_LIMIT','公告最多显示条数','200'),('DEFAULT_DURATION_MINUTES','默认任务时长（分钟）','60');
CREATE TABLE IF NOT EXISTS mm_notice(id BIGINT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(200) NOT NULL,content TEXT NOT NULL,kind VARCHAR(20) NOT NULL,target_role BIGINT NULL,published_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NULL,actor_id BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_notice_read(id BIGINT PRIMARY KEY AUTO_INCREMENT,notice_id BIGINT NOT NULL,user_id BIGINT NOT NULL,read_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_read(notice_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_line_stock(id BIGINT PRIMARY KEY AUTO_INCREMENT,work_order_id BIGINT NOT NULL,material_id BIGINT NOT NULL,lot_id BIGINT NOT NULL,quantity DECIMAL(18,6) NOT NULL DEFAULT 0,UNIQUE KEY uq_line(work_order_id,material_id,lot_id),CHECK(quantity>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_line_movement(id BIGINT PRIMARY KEY AUTO_INCREMENT,work_order_id BIGINT NOT NULL,material_id BIGINT NOT NULL,lot_id BIGINT NOT NULL,quantity DECIMAL(18,6) NOT NULL,kind VARCHAR(32) NOT NULL,source_id BIGINT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_line_move(kind,source_id,material_id,lot_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_task_consumption(id BIGINT PRIMARY KEY AUTO_INCREMENT,operation_id BIGINT NOT NULL,material_id BIGINT NOT NULL,quantity_per_unit DECIMAL(18,6) NOT NULL,UNIQUE KEY uq_consume(operation_id,material_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_work_consumption(id BIGINT PRIMARY KEY AUTO_INCREMENT,work_order_id BIGINT NOT NULL,operation_id BIGINT NOT NULL,material_id BIGINT NOT NULL,quantity_per_unit DECIMAL(18,6) NOT NULL,UNIQUE KEY uq_work_consume(work_order_id,operation_id,material_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_work_output(id BIGINT PRIMARY KEY AUTO_INCREMENT,work_order_id BIGINT NOT NULL,operation_id BIGINT NOT NULL,material_id BIGINT NULL,is_key INT NOT NULL,UNIQUE KEY uq_work_output(work_order_id,operation_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_nc(id BIGINT PRIMARY KEY AUTO_INCREMENT,inspection_id BIGINT NOT NULL UNIQUE,task_id BIGINT NULL,defect_id BIGINT NULL,quantity DECIMAL(18,2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'OPEN',decision VARCHAR(20) NULL,reason VARCHAR(500) NULL,approved_by BIGINT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_rework(id BIGINT PRIMARY KEY AUTO_INCREMENT,nc_id BIGINT NOT NULL UNIQUE,task_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',result VARCHAR(500) NULL,completed_by BIGINT NULL,completed_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_document(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(80) NOT NULL UNIQUE,kind VARCHAR(32) NOT NULL,source_id BIGINT NULL,warehouse_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',reason VARCHAR(500) NULL,actor_id BIGINT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,posted_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CALL mm5_add_column('mm_document','name','VARCHAR(100) NULL');
CALL mm5_add_column('mm_document','business_date','DATE NULL');
CREATE TABLE IF NOT EXISTS mm_report_sheet(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(80) NOT NULL UNIQUE,task_id BIGINT NOT NULL,reporter_id BIGINT NOT NULL,good_quantity INT NOT NULL,bad_quantity INT NOT NULL,report_time DATETIME NOT NULL,remark VARCHAR(500) NULL,created_by BIGINT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',approved_by BIGINT NULL,approval_note VARCHAR(500) NULL,report_id BIGINT NULL,approved_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_document_line(id BIGINT PRIMARY KEY AUTO_INCREMENT,document_id BIGINT NOT NULL,material_id BIGINT NOT NULL,lot_id BIGINT NOT NULL,location_id BIGINT NULL,quantity DECIMAL(18,2) NOT NULL,source_line_id BIGINT NULL,CHECK(quantity>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CALL mm5_add_column('mm_document_line','input_unit_id','BIGINT NULL');
CALL mm5_add_column('mm_document_line','entered_quantity','DECIMAL(18,6) NULL');
CREATE TABLE IF NOT EXISTS mm_document_check(id BIGINT PRIMARY KEY AUTO_INCREMENT,line_id BIGINT NOT NULL,template_id BIGINT NOT NULL,quantity DECIMAL(18,2) NOT NULL,qualified_quantity DECIMAL(18,2) NOT NULL,results JSON NOT NULL,status VARCHAR(20) NOT NULL,actor_id BIGINT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_package(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(80) NOT NULL UNIQUE,customer_id BIGINT NULL,order_id BIGINT NULL,length_mm DECIMAL(18,2) NOT NULL,width_mm DECIMAL(18,2) NOT NULL,height_mm DECIMAL(18,2) NOT NULL,net_weight DECIMAL(18,2) NOT NULL,gross_weight DECIMAL(18,2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',parent_id BIGINT NULL,created_by BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_package_item(id BIGINT PRIMARY KEY AUTO_INCREMENT,package_id BIGINT NOT NULL,inventory_id BIGINT NOT NULL,quantity DECIMAL(18,2) NOT NULL,UNIQUE KEY uq_package_item(package_id,inventory_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_task_slot(id BIGINT PRIMARY KEY AUTO_INCREMENT,task_id BIGINT NOT NULL UNIQUE,station_id BIGINT NOT NULL,owner_id BIGINT NOT NULL,start_at DATETIME NOT NULL,end_at DATETIME NOT NULL,quantity INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_work_relation(id BIGINT PRIMARY KEY AUTO_INCREMENT,parent_work_order_id BIGINT NOT NULL,child_work_order_id BIGINT NOT NULL UNIQUE,material_id BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_job_run(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(80) NOT NULL,started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at DATETIME NULL,status VARCHAR(20) NOT NULL,error VARCHAR(500) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_job_config(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,enabled INT NOT NULL DEFAULT 1,interval_seconds INT NOT NULL,last_run DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO mm_job_config(code,name,interval_seconds) VALUES('EQUIPMENT_CHECK','设备到期任务',60),('REPORT_QC','报工质检事件',2);
SET @old_unique=(SELECT index_name FROM(SELECT index_name,GROUP_CONCAT(column_name ORDER BY seq_in_index) cols FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='mm_task_context' AND non_unique=0 AND index_name<>'PRIMARY' GROUP BY index_name)x WHERE cols='work_order_id,operation_id' LIMIT 1);
SET @drop_unique=IF(@old_unique IS NULL,'SELECT 1',CONCAT('ALTER TABLE mm_task_context DROP INDEX `',@old_unique,'`'));
PREPARE s FROM @drop_unique; EXECUTE s; DEALLOCATE PREPARE s;
UPDATE t_equipment SET status='NORMAL' WHERE status='1'; -- Preserve the documented meaning of legacy status 1.
UPDATE mm_operation o JOIN(SELECT route_id,MAX(sequence_no) last_seq FROM mm_operation GROUP BY route_id HAVING SUM(is_key)=0)x ON x.route_id=o.route_id AND x.last_seq=o.sequence_no SET o.is_key=1; -- Legacy routes used the last operation as their completion measure.
